BEGIN;
DO $$ DECLARE actor uuid;member_actor uuid;s uuid;other_s uuid;source uuid;source_team uuid;other_team uuid;eligible uuid;value jsonb;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active)VALUES('fictional-member-picker-admin@example.test','fictional-proof','admin',true)RETURNING id INTO actor;
 INSERT INTO public.admin_users(email,password_hash,role,is_active)VALUES('fictional-member-picker-account@example.test','fictional-proof','team_member',true)RETURNING id INTO member_actor;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(actor,repeat('a',64))RETURNING id INTO s;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(member_actor,repeat('b',64))RETURNING id INTO other_s;
 INSERT INTO public.admin_teams(name,slug)VALUES('Fictional picker owner','fictional-picker-owner')RETURNING id INTO source_team;
 INSERT INTO public.admin_teams(name,slug)VALUES('Fictional other scope','fictional-picker-other')RETURNING id INTO other_team;
 INSERT INTO public.members(name,email,team_id)VALUES('Fictional source','fictional-picker-source@example.test',source_team)RETURNING id INTO source;
 INSERT INTO public.members(name,email,team_id)SELECT 'A other scope '||n,'fictional-picker-other-'||n||'@example.test',other_team FROM generate_series(1,40)n;
 INSERT INTO public.members(name,email,team_id)SELECT 'Eligible '||lpad(n::text,3,'0'),'fictional-picker-eligible-'||n||'@example.test',source_team FROM generate_series(1,65)n;
 INSERT INTO public.members(name,email,team_id,is_active)VALUES('Ineligible inactive','fictional-picker-inactive@example.test',source_team,false);
 INSERT INTO public.members(name,email,team_id,deleted_at)VALUES('Ineligible archived','fictional-picker-archived@example.test',source_team,now());
 value:=public.member_merge_candidates(actor,s,source,1,'');
 IF(value->>'total')::integer<>65 OR jsonb_array_length(value->'items')<>30 OR value::text LIKE '%other scope%' OR value::text LIKE '%Ineligible%' OR value::text LIKE '%Fictional source%' THEN RAISE EXCEPTION 'Merge candidates were filtered after paging or disclosed ineligible scope';END IF;
 value:=public.member_merge_candidates(actor,s,source,3,'');IF jsonb_array_length(value->'items')<>5 THEN RAISE EXCEPTION 'Later eligible merge candidates inaccessible';END IF;
 value:=public.member_merge_candidates(actor,s,source,1,'eligible 065');IF(value->>'total')::integer<>1 THEN RAISE EXCEPTION 'Candidate search omitted later exact match';END IF;
 eligible:=(value->'items'->0->>'id')::uuid;value:=public.member_merge_target(actor,s,source,eligible);
 IF value->'member'->>'name'<>'Eligible 065' OR(value->>'sourceRevision')::integer<>1 THEN RAISE EXCEPTION 'Current target metadata incorrect';END IF;
 UPDATE public.members SET team_id=other_team WHERE id=eligible;
 BEGIN PERFORM public.member_merge_target(actor,s,source,eligible);RAISE EXCEPTION 'Changed target scope disclosed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 BEGIN PERFORM public.member_merge_candidates(member_actor,other_s,source,1,'');RAISE EXCEPTION 'Unprivileged member enumerated merge targets';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 INSERT INTO public.admin_teams(name,slug)SELECT 'Fictional destination '||lpad(n::text,3,'0'),'fictional-destination-'||n FROM generate_series(1,105)n;
 value:=public.member_creation_destinations(actor,s,2);IF(value->>'total')::integer<>107 OR jsonb_array_length(value->'items')<>7 THEN RAISE EXCEPTION 'Create destinations silently truncated after 100';END IF;
 value:=public.member_creation_destinations(member_actor,other_s,1);IF(value->>'total')::integer<>0 THEN RAISE EXCEPTION 'Destination inventory bypassed current team rights';END IF;
 UPDATE public.admin_sessions SET revoked_at=now() WHERE id=s;
 BEGIN PERFORM public.member_merge_candidates(actor,s,source,1,'');RAISE EXCEPTION 'Revoked session enumerated candidates';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 BEGIN PERFORM public.member_creation_destinations(actor,s,1);RAISE EXCEPTION 'Revoked session enumerated destinations';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 IF has_function_privilege('anon','public.member_merge_candidates(uuid,uuid,uuid,integer,text)','EXECUTE') OR has_function_privilege('authenticated','public.member_merge_target(uuid,uuid,uuid,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.member_creation_destinations(uuid,uuid,integer)','EXECUTE') THEN RAISE EXCEPTION 'Member selection reader grants incorrect';END IF;
END $$;
ROLLBACK;
